import PropTypes from "prop-types";
import React from "react";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
} from "./CommonRuleRedux";
import { compose } from "redux";
import { connect } from "react-redux";
import ConditionRow from "./ConditionRow";
import Operator from "./Operator";

import * as style from "./CommonRule.styles";

class Condition extends React.Component {
  constructor(props) {
    super(props);
  }

  renderCondition(condition, index, initialMargin, lastOperator) {
    const { componentIndex } = this.props;
    let margin = initialMargin;
    if (condition) {
      if (
        condition &&
        condition.root &&
        (condition.root.toUpperCase() === "AND" ||
          condition.root.toUpperCase() === "OR" ||
          condition.root.toUpperCase() === "NOT")
      ) {
        if (lastOperator && lastOperator !== condition.root) {
          margin += 35;
        }
        if (
          condition.root.toUpperCase() === "AND" ||
          condition.root.toUpperCase() === "OR"
        ) {
          return (
            <div key={index}>
              {this.renderCondition(
                condition.leaf[0],
                index.concat(["leaf", Number(0)]),
                margin,
                condition.root
              )}
              <Operator
                condition={condition}
                componentIndex={componentIndex}
                index={index}
                margin={margin}
                value={condition.root}
              />
              {this.renderCondition(
                condition.leaf[1],
                index.concat(["leaf", Number(1)]),
                margin,
                condition.root
              )}
            </div>
          );
        }
        return (
          <div key={index}>
            <Operator
              condition={condition}
              componentIndex={componentIndex}
              index={index}
              margin={margin}
              value={condition.root}
            />{" "}
            {this.renderCondition(
              condition.leaf[0],
              index.concat(["leaf", Number(0)]),
              margin,
              condition.root
            )}
          </div>
        );
      }
      return (
        <div
          key={index}
          className={style.conditionHelperLine}
          style={{ marginLeft: margin }}
        >
          <ConditionRow
            condition={condition}
            componentIndex={componentIndex}
            index={index}
          />
        </div>
      );
    }
  }

  render() {
    const { condition, index } = this.props;
    return <div>{this.renderCondition(condition, index, 10, "")}</div>;
  }
}

Condition.propTypes = {
  condition: PropTypes.object.isRequired,
  componentIndex: PropTypes.number.isRequired,
  index: PropTypes.number.isRequired,
};

export default compose(
  applyReducers(commonRulesReducers),
  connect(null, commonRulesMapDisToProps)
)(Condition);
